import{_ as a,o,c as t,a3 as n}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Calendar — Deployment","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar — Deployment | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar — Deployment | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/calendar"}]]},"headers":[],"relativePath":"deployment/calendar.md","filePath":"deployment/calendar.md","lastUpdated":1791561813000}'),r={name:"deployment/calendar.md"};function d(l,e,i,c,s,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="calendar-—-deployment" tabindex="-1">Calendar — Deployment <a class="header-anchor" href="#calendar-—-deployment" aria-label="Permalink to &quot;Calendar — Deployment&quot;">​</a></h1><h2 id="migrate-only" tabindex="-1">Migrate-only <a class="header-anchor" href="#migrate-only" aria-label="Permalink to &quot;Migrate-only&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>Creates <code>calendar_events</code>, registers the <code>calendar</code> catalog module (free CRM opt-in), and grants missing default-role permissions (<code>calendar.view|create|update|delete|view_all|manage_integrations</code>).</p><p>Do <strong>not</strong> rely on <code>db:seed</code> in production for catalog/RBAC.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><ul><li><strong>1.1.0</strong> — Task/Lead/Project overlays</li><li><strong>1.2.0</strong> — Meeting invitee list/view ACL (<code>read_only</code> on resource)</li><li><strong>1.3.0</strong> — Manual event shares (<code>calendar_event_shares</code>, viewer/editor)</li><li><strong>1.4.0</strong> — Google/Outlook sync Phase 1 (<code>calendar_provider_connections</code>; <code>external_provider</code>/<code>external_event_id</code> on <code>calendar_events</code>; <code>calendar.manage_integrations</code> permission)</li><li><strong>1.5.0</strong> — Push Meeting / Task / Lead overlays to connected Google/Outlook (same job + soft-fail)</li><li><strong>1.6.0</strong> — Inbound pull (provider → EloSync) as read-only External events; Sync now + hourly schedule</li><li><strong>1.7.0</strong> — Push Project / Contact / Company overlays</li><li><strong>1.8.0</strong> — Webhook-driven near-real-time inbound (watches + public webhooks; hourly pull as backstop)</li><li><strong>1.9.0</strong> — Named team/department calendars (<code>calendars</code> table, <code>calendar_id</code>, <code>calendar.manage_calendars</code>)</li></ul><p>Bump: migrate-only through <code>2026_10_08_170000_bump_calendar_module_to_1_9_0</code> (do <strong>not</strong> <code>db:seed</code>).</p><h2 id="environment-calendar-sync-—-1-4-0" tabindex="-1">Environment (Calendar sync — 1.4.0+) <a class="header-anchor" href="#environment-calendar-sync-—-1-4-0" aria-label="Permalink to &quot;Environment (Calendar sync — 1.4.0+)&quot;">​</a></h2><p>Google/Microsoft OAuth apps are <strong>platform-wide</strong> (unlike Meetings, which is per-workspace). Set in platform <code>.env</code>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GOOGLE_CALENDAR_CLIENT_ID</code> / <code>GOOGLE_CALENDAR_CLIENT_SECRET</code></td><td>Google Calendar API OAuth app; leave unset to disable Google Connect (SPA shows &quot;not configured&quot;)</td></tr><tr><td><code>MICROSOFT_CALENDAR_CLIENT_ID</code> / <code>MICROSOFT_CALENDAR_CLIENT_SECRET</code> / <code>MICROSOFT_CALENDAR_TENANT</code></td><td>Microsoft Graph OAuth app (<code>MICROSOFT_CALENDAR_TENANT</code> defaults to <code>common</code>); leave unset to disable Outlook Connect</td></tr><tr><td><code>APP_URL</code></td><td>Builds the fixed OAuth callback and webhook base: <code>/api/oauth/calendar-sync/{provider}/callback</code>, <code>/webhooks/calendar-sync/{provider}</code> (HTTPS in production)</td></tr><tr><td><code>FRONTEND_URL</code></td><td>SPA return URL after OAuth (<code>/#/calendar?integrations=…</code>)</td></tr><tr><td><code>CALENDAR_SYNC_PROVIDERS_FAKE</code></td><td>Optional local/CI only; <strong>ignored / forced off in production</strong></td></tr></tbody></table><p>Register the platform callback URL once on each OAuth app (Google Cloud Console / Azure AD app registration) — not per tenant. For <strong>1.8.0</strong>, also register the public webhook notification URL with each provider.</p><h2 id="smoke" tabindex="-1">Smoke <a class="header-anchor" href="#smoke" aria-label="Permalink to &quot;Smoke&quot;">​</a></h2><ol><li>Confirm marketplace module <code>calendar</code> exists and is installed on a test workspace.</li><li>Owner: <code>GET /api/tenant/v1/calendar/events</code> → 200.</li><li>Create event → appears on Week (default), Day, Month, and Agenda.</li><li>On Week/Day, drag an event to a new slot → persists after refresh (<code>PUT</code> succeeds; toast “Event rescheduled”).</li><li>Staff without <code>view_all</code> cannot list another user’s <strong>manual</strong> events unless shared.</li><li>Meeting invitee (staff) lists/views the projected meeting event with <code>read_only: true</code>; <code>PUT</code>/<code>cancel</code>/<code>DELETE</code> → 403.</li><li>Share a manual event as viewer → sharee lists with <code>read_only: true</code>; as editor → can mutate.</li><li>Dashboard includes <code>calendar</code> upcoming widget when entitled (invitee/share scope included).</li></ol><p>Go-live: <a href="/deployment/calendar-invitee-acl-1-2-0-production-readiness">Invitee ACL 1.2.0</a> · <a href="/deployment/calendar-event-shares-1-3-0-production-readiness">Shares 1.3.0</a> · <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">Sync 1.4.0</a> · <a href="/deployment/calendar-overlay-provider-push-1-5-0-production-readiness">Overlay push 1.5.0</a> · <a href="/deployment/calendar-two-way-inbound-1-6-0-production-readiness">Inbound 1.6.0</a> · <a href="/deployment/calendar-overlay-provider-push-1-7-0-production-readiness">P/C/C push 1.7.0</a> · <a href="/deployment/calendar-webhook-inbound-1-8-0-production-readiness">Webhooks 1.8.0</a> · <a href="/deployment/calendar-named-calendars-1-9-0-production-readiness">Named calendars 1.9.0</a>.</p><h3 id="smoke-calendar-sync-—-1-4-0–1-8-0" tabindex="-1">Smoke (Calendar sync — 1.4.0–1.8.0) <a class="header-anchor" href="#smoke-calendar-sync-—-1-4-0–1-8-0" aria-label="Permalink to &quot;Smoke (Calendar sync — 1.4.0–1.8.0)&quot;">​</a></h3><ol start="9"><li>Admin with <code>calendar.manage_integrations</code>: Calendar → <strong>Sync</strong> lists Google + Microsoft; Connect disabled when platform OAuth env is unset; copy mentions Meeting/Task/Lead/Project/Contact/Company overlays and near-real-time inbound.</li><li>After Connect (staging OAuth app): create manual event → appears in provider calendar; update/cancel in EloSync propagates (async — confirm Horizon <strong><code>calendar-sync</code></strong> worker).</li><li>With Connect active: create a Task with <code>due_at</code>, a Lead follow-up, a Meeting, and a Project/Contact/Company overlay → each appears on the provider calendar; clear due / cancel → provider event cancelled.</li><li>Sync now / provider-side create → External event; “Near real-time” badge when watch is active; scheduler runs hourly pull + daily watch renewal.</li><li>Organizer disconnects provider → new events no longer push/pull (existing provider copies remain).</li></ol><h3 id="smoke-named-calendars-—-1-9-0" tabindex="-1">Smoke (Named calendars — 1.9.0) <a class="header-anchor" href="#smoke-named-calendars-—-1-9-0" aria-label="Permalink to &quot;Smoke (Named calendars — 1.9.0)&quot;">​</a></h3><ol start="14"><li>Admin/manager: <strong>Manage calendars</strong> → create named calendar (optional department when Departments installed).</li><li>Create event on that calendar → filter chip shows it; department member sees it; outsider without <code>view_all</code> does not.</li></ol><h2 id="rollback-note" tabindex="-1">Rollback note <a class="header-anchor" href="#rollback-note" aria-label="Permalink to &quot;Rollback note&quot;">​</a></h2><p>Catalog/permission data migrations are intentionally irreversible; use a forward migration to retire the module if required. Roll catalog bumps only with matching code rollback.</p>',21)])])}const u=a(r,[["render",d]]);export{m as __pageData,u as default};
